import{_ as n,a0 as a,w as s,s as p,ao as l,I as r,x as e,a1 as o,A as d}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const M=JSON.parse('{"title":"使用 gedit 文本編輯器優化你的 GNOME 體驗 | LCTT x X-CMD","titleTemplate":false,"description":"使用 gedit 文本編輯器優化你的 GNOME 體驗 | LCTT (202012) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 gedit 文本編輯器優化你的 GNOME 體驗 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 gedit 文本編輯器優化你的 GNOME 體驗 | LCTT (202012) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202012/20201207 Optimize your GNOME experience with the Gedit text editor","title":"使用 gedit 文本編輯器優化你的 GNOME 體驗","tag":"202012","desc":""},"relativePath":"202012/20201207 Optimize your GNOME experience with the Gedit text editor.md","filePath":"[post].md"}'),g={name:"202012/20201207 Optimize your GNOME experience with the Gedit text editor.md"};function u(m,t,f,x,h,T){const i=a("Link");return s(),p("div",null,[t[23]||(t[23]=l('<h1 id="使用-gedit-文本編輯器優化你的-gnome-體驗" tabindex="-1">使用 gedit 文本編輯器優化你的 GNOME 體驗 <a class="header-anchor" href="#使用-gedit-文本編輯器優化你的-gnome-體驗" aria-label="Permalink to “使用 gedit 文本編輯器優化你的 GNOME 體驗”">​</a></h1><blockquote><p>它是一個可以完成工作的簡約編輯器，並以隱藏的增強功能使得事情更簡單。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202012/19/110419snchihpnjn8juxqc.jpg" alt=""></p><p>作為默認的文本編輯器是一項吃力不討好的工作。人們通常把默認文本編輯器幾乎看作是一個演示應用、一個稍微好一點的 “hello World” 示例，説明應用在該平台上的是如何運行的。在極少數情況下，當用户需要將一些文本保存到一個可能永遠不會再看的文件中時，用户會找到默認文本編輯器。對於“嚴肅”的工作，他們會轉向文字處理器或 IDE，或終端中的編輯器，或者至少是一個不同的文本編輯器，必須像“真正的”應用一樣下載和安裝。</p><p>很奇怪，默認的文本編輯器很難被人重視，然而 GNOME 桌面的編輯器 gedit 卻被廣泛認為是一個真正有價值的文本編輯器，超越了它所在的桌面。它被用作網頁設計課程的必備文本編輯器，是新手開發者和系統管理員的推薦工具，也是許多桌面 Linux 用户最喜歡的可靠夥伴。</p><h3 id="安裝-gedit" tabindex="-1">安裝 gedit <a class="header-anchor" href="#安裝-gedit" aria-label="Permalink to “安裝 gedit”">​</a></h3><p>如果你運行的是 GNOME 桌面，你可能已經安裝了 gedit，儘管它可能只作為“文本編輯器”出現在你的應用菜單中。如果你不確定，只需在你的活動界面中輸入 <code>gedit</code>，然後在打開的文本編輯器中進入 “About” 菜單項。</p><p><img src="https://opensource.com/sites/default/files/uploads/gedit-31_days_gedit-opensource.jpg" alt="gedit terminal box with black background and white letters" title="gedit terminal box with black background and white letters"></p>',8)),r("p",null,[t[1]||(t[1]=e("在 Windows 上，你可以",-1)),o(i,{href:"https://www.microsoft.com/en-nz/p/gedit"},{default:d(()=>[...t[0]||(t[0]=[e("從微軟商店下載並安裝 gedit",-1)])]),_:1}),t[2]||(t[2]=e("。",-1))]),r("p",null,[t[5]||(t[5]=e("在 Mac 上，你可以",-1)),o(i,{href:"https://opensource.com/article/20/6/homebrew-mac"},{default:d(()=>[...t[3]||(t[3]=[e("使用 Homebrew",-1)])]),_:1}),t[6]||(t[6]=e("或 ",-1)),o(i,{href:"https://opensource.com/article/20/11/macports"},{default:d(()=>[...t[4]||(t[4]=[e("MacPorts",-1)])]),_:1}),t[7]||(t[7]=e(" 安裝 gedit。",-1))]),t[24]||(t[24]=l('<h3 id="使用-gedit" tabindex="-1">使用 gedit <a class="header-anchor" href="#使用-gedit" aria-label="Permalink to “使用 gedit”">​</a></h3><p>當你第一次啓動 gedit 時，你會看到一個簡約的界面，包括一個文本輸入面板、一個標題欄和一個位於窗口底部的狀態面板。底部的狀態面板提供了一些常用的設置：你想使用哪種語法高亮模式、你喜歡的製表符寬度、以及一些流行的偏好，如行號、文本換行等等。這些選項中的大部分也可以在 “Preferences” 菜單中進行全局設置，它可在應用程序右上角的 “漢堡” 樣式的菜單中找到。</p><h3 id="gedit-的隱藏功能" tabindex="-1">gedit 的隱藏功能 <a class="header-anchor" href="#gedit-的隱藏功能" aria-label="Permalink to “gedit 的隱藏功能”">​</a></h3><p>從表面上看，gedit 正是它所標榜的那樣：一個不起眼的文本編輯器，它不會妨礙你的工作，因此你可以在屏幕上的框中輸入字母。但是，這個簡單的文本編輯器卻隱藏着一些你可能不知道的令人興奮的功能，即使你已經使用它多年。</p><p>這些鍵盤功能在 gedit 中並沒有被記錄下來：</p><ul><li><code>Ctrl+D</code> 刪除當前行。這對於編碼者或以標記格式（如 Asciidoc、reST 或 CommonMark）寫作的人特別有用。</li><li><code>Ctrl+I</code> 會彈出 “Go to Line” 下拉框。輸入一個數字，你就會立即跳到該行。</li><li><code>Alt+向上箭頭</code> 或 <code>Alt+向下箭頭</code> 會抓取當前行，並將它在文檔中向上或向下移動。</li><li><code>Alt+向左箭頭</code> 或 <code>Alt+向右箭頭</code> 抓取最近的單詞（在光標左側）並將其向左或向右移動。</li><li>要輸入特殊的 Unicode 字符，請按下 <code>Shift+Ctrl+U</code> 並鬆開，然後輸入 Unicode 字符代碼。你通常必須查找字符代碼（除非你已經記住了一些，但誰有記性來記住這些字符代碼？）例如，要打出一隻企鵝，按下 <code>Shift+Ctrl+U</code> 然後鬆開。當你鬆開按鍵後，你會看到一個帶下劃線的 U，然後輸入 <code>1F427</code>，後面跟一個空格，你的 Unicode 字符就會變成一個友好的 <code>🐧</code>。誠然，這並不完全是 gedit 所獨有的，但這是個很有用的技巧，而且它在 gedit 中也確實有效。</li></ul><h3 id="穩定簡單" tabindex="-1">穩定簡單 <a class="header-anchor" href="#穩定簡單" aria-label="Permalink to “穩定簡單”">​</a></h3><p>Gedit 很像 GNOME 本身。它客觀上比許多同類軟件（比如 KDE 的 Kate）更簡單，但它仍然能夠滿足你日常 80% 或 90% 的期望。</p><p>當然，可能會有一些任務 gedit 不是最佳工具。你可能會發現自己要深入研究一些獨特的日誌文件，或者需要一個精確的解析器或代碼檢查器，你會轉向專門的應用。這沒關係。gedit 並不意味着對所有用户都適用。但對於那些需要文本編輯器的人來説，它是一個很好的文本編輯器，有時這就是所需要的。在 Linux 或者在任何你正在使用的平台上，試一下 gedit，因為它很有可能是一個比默認應用的更好的選擇。</p><hr>',10)),r("p",null,[t[9]||(t[9]=e("via: ",-1)),o(i,{href:"https://opensource.com/article/20/12/gedit"},{default:d(()=>[...t[8]||(t[8]=[e("https://opensource.com/article/20/12/gedit",-1)])]),_:1})]),r("p",null,[t[14]||(t[14]=e("作者：",-1)),o(i,{href:"https://opensource.com/users/seth"},{default:d(()=>[...t[10]||(t[10]=[e("Seth Kenlon",-1)])]),_:1}),t[15]||(t[15]=e(" 選題：",-1)),o(i,{href:"https://github.com/lujun9972"},{default:d(()=>[...t[11]||(t[11]=[e("lujun9972",-1)])]),_:1}),t[16]||(t[16]=e(" 譯者：",-1)),o(i,{href:"https://github.com/geekpi"},{default:d(()=>[...t[12]||(t[12]=[e("geekpi",-1)])]),_:1}),t[17]||(t[17]=e(" 校對：",-1)),o(i,{href:"https://github.com/wxy"},{default:d(()=>[...t[13]||(t[13]=[e("wxy",-1)])]),_:1})]),r("p",null,[t[20]||(t[20]=e("本文由 ",-1)),o(i,{href:"https://github.com/LCTT/TranslateProject"},{default:d(()=>[...t[18]||(t[18]=[e("LCTT",-1)])]),_:1}),t[21]||(t[21]=e(" 原創編譯，",-1)),o(i,{href:"https://linux.cn/"},{default:d(()=>[...t[19]||(t[19]=[e("Linux中國",-1)])]),_:1}),t[22]||(t[22]=e(" 榮譽推出",-1))])])}const N=n(g,[["render",u]]);export{M as __pageData,N as default};
